<?php get_header();while(have_posts()):the_post();$price=get_post_meta(get_the_ID(),'_rrv_price',true);$amenities=array_filter(array_map('trim',explode(',',get_post_meta(get_the_ID(),'_rrv_amenities',true))));?><section class="rrv-content"><div class="rrv-container"><div class="rrv-split"><div><?php if(has_post_thumbnail())the_post_thumbnail('large',['style'=>'border-radius:28px']);?></div><div><div class="rrv-kicker">Room at Royal Rest Villa</div><h1><?php the_title();?></h1><p class="rrv-lead"><?php echo esc_html(get_the_excerpt());?></p><?php if($price):?><h3><?php echo esc_html(get_theme_mod('rrv_currency','KES').' '.$price);?> <small>/ night</small></h3><?php endif;?><div class="rrv-checks"><?php foreach($amenities as $a)echo '<div class="rrv-check">'.esc_html($a).'</div>';?></div><a class="rrv-btn rrv-btn--gold" href="<?php echo esc_url(rrv_booking_url().'?room='.rawurlencode(get_the_title()));?>">Book this room</a></div></div><div class="rrv-content__wrap" style="margin-top:60px"><?php the_content();?></div></div></section><?php endwhile;get_footer(); ?>